def countValidSelections(nums):
    total = sum(nums)
    left = 0
    count = 0
    for x in nums:
        if x == 0:
            right = total - left
            if left == right:
                count += 2  # both directions work
            elif abs(left - right) == 1:
                count += 1  # exactly one direction works
        left += x
    return count
